@pytest.mark.asyncio
async def test_ocr_image_png() -> None:
    """OCR: PNG image extraction with OCR enabled. In WASM this exercises the Uint8Array bridge parameter and Promise await in the generated OcrBackend bridge."""
    input = ExtractInput(
        bytes=Path("test_documents/images/test_hello_world.png").read_bytes(),
        config={},
        filename="test_hello_world.png",
        kind=ExtractInputKind("bytes"),
        mime_type="image/png",
    )
    config = ExtractionConfig()

    result = await extract(input, config)
    assert _alef_e2e_text(result.results[0].mime_type).lower() == "image/png".lower()
    assert len(result.results[0].content) >= 1
    assert any(v.lower() in str(result.results[0].content).lower() for v in ["Hello", "World", "hello", "world"])


